class AsyncMCPOAuthAuthorizations(AsyncAPIResource):
    async def create(
        self,
        *,
        mcp_server_url: str,
        vault_id: str,
        client_id: Union[str, Omit] = omit,
        scope: Union[str, Omit] = omit,
        display_name: Union[Optional[str], Omit] = omit,
        idempotency_key: Optional[str] = None,
        extra_headers: Optional[Headers] = None,
        extra_query: Optional[Query] = None,
        extra_body: Optional[Body] = None,
        timeout: Union[float, httpx2.Timeout, None, NotGiven] = not_given,
    ) -> _models.CreateMCPOAuthAuthorizationResponse:
        """Start an MCP OAuth authorization. Starts the flow for `mcp_server_url`; the user opens `authorization_url`, and the completed flow stores the credential in `vault_id`."""
        extra_headers = {"Idempotency-Key": idempotency_key or str(uuid.uuid4()), **(extra_headers or {})}
        return await self._post(
            "/v1/mcp_oauth_authorizations",
            body={
                "mcp_server_url": mcp_server_url,
                "vault_id": vault_id,
                "client_id": client_id,
                "scope": scope,
                "display_name": display_name,
            },
            options=make_request_options(
                extra_headers=extra_headers, extra_query=extra_query, extra_body=extra_body, timeout=timeout
            ),
            cast_to=_models.CreateMCPOAuthAuthorizationResponse,
        )

    async def retrieve(
        self,
        authorization_id: str,
        *,
        extra_headers: Optional[Headers] = None,
        extra_query: Optional[Query] = None,
        extra_body: Optional[Body] = None,
        timeout: Union[float, httpx2.Timeout, None, NotGiven] = not_given,
    ) -> _models.MCPOAuthAuthorization:
        """Get an MCP OAuth authorization."""
        if not authorization_id:
            raise ValueError(f"Expected a non-empty value for `authorization_id` but received {authorization_id!r}")
        return await self._get(
            path_template("/v1/mcp_oauth_authorizations/{authorization_id}", authorization_id=authorization_id),
            options=make_request_options(
                extra_headers=extra_headers, extra_query=extra_query, extra_body=extra_body, timeout=timeout
            ),
            cast_to=_models.MCPOAuthAuthorization,
        )

    async def complete(
        self,
        *,
        state: str,
        code: Union[str, Omit] = omit,
        error: Union[str, Omit] = omit,
        error_description: Union[str, Omit] = omit,
        iss: Union[str, Omit] = omit,
        extra_headers: Optional[Headers] = None,
        extra_query: Optional[Query] = None,
        extra_body: Optional[Body] = None,
        timeout: Union[float, httpx2.Timeout, None, NotGiven] = not_given,
    ) -> _models.MCPOAuthAuthorization:
        """Complete an MCP OAuth authorization. The authorization server's redirect parameters, relayed by the page the user returned to."""
        return await self._post(
            "/v1/mcp_oauth/callback",
            body={"state": state, "code": code, "error": error, "error_description": error_description, "iss": iss},
            options=make_request_options(
                extra_headers=extra_headers, extra_query=extra_query, extra_body=extra_body, timeout=timeout
            ),
            cast_to=_models.MCPOAuthAuthorization,
        )


